const items = $input.all();
const cleanedData = [];
const seenEmails = new Set();
const seenPhones = new Set();

// Counters for our Summary Report
let totalImported = items.length;
let removedEmpty = 0;
let removedDuplicate = 0;
let removedInvalidEmail = 0;
let removedInvalidPhone = 0;
let removedInvalidDate = 0;

let customerCounter = 1;

for (const item of items) {
  let name = item.json['Full Name'] ? String(item.json['Full Name']) : '';
  let email = item.json['Email'] ? String(item.json['Email']) : '';
  let phone = item.json['Phone No'] ? String(item.json['Phone No']) : '';
  let city = item.json['City'] ? String(item.json['City']) : '';
  let regDate = item.json['Registration Date'] ? String(item.json['Registration Date']) : '';

  // ❌ Step 2: Remove Empty Rows
  if (!name.trim() && !email.trim() && !phone.trim()) {
    removedEmpty++;
    continue; 
  }

  // ✂️ Step 3: Trim Extra Spaces
  name = name.trim().replace(/\s+/g, ' ');
  email = email.trim().replace(/\s+/g, '');
  phone = phone.trim().replace(/\s+/g, '');
  city = city.trim().replace(/\s+/g, ' ');

  // 🔠 Step 4: Standardize Capitalization
  const toProperCase = (str) => str.toLowerCase().replace(/\b\w/g, char => char.toUpperCase());
  name = toProperCase(name);
  city = toProperCase(city);

  // 📧 Step 5: Validate Email Addresses
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    removedInvalidEmail++;
    continue; 
  }

  // 📱 Step 6: Validate Phone Numbers
  let cleanPhone = phone.replace(/[-+()]/g, '');
  if (cleanPhone.startsWith('8801')) {
    cleanPhone = cleanPhone.substring(2);
  }
  const bdPhoneRegex = /^01[3-9]\d{8}$/;
  if (!bdPhoneRegex.test(cleanPhone)) {
    removedInvalidPhone++;
    continue; 
  }

  // 📅 Step 7: Standardize Dates
  let formattedDate = '';
  if (regDate) {
    const parsedDate = Date.parse(regDate);
    if (!isNaN(parsedDate)) {
      const d = new Date(parsedDate);
      formattedDate = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
    } else {
      removedInvalidDate++;
      continue; 
    }
  } else {
    removedInvalidDate++;
    continue; 
  }

  // 👥 Step 8: Remove Duplicate Records
  if (seenEmails.has(email.toLowerCase()) || seenPhones.has(cleanPhone)) {
    removedDuplicate++;
    continue; 
  }
  seenEmails.add(email.toLowerCase());
  seenPhones.add(cleanPhone);

  // 🎁 Bonus 1: Generate Customer ID (e.g., CUST-0001, CUST-0002)
  const customerId = `CUST-${String(customerCounter).padStart(4, '0')}`;
  customerCounter++;

  // Step 9: Save the customer record
  cleanedData.push({
    json: {
      'Customer ID': customerId,
      'Full Name': name,
      'Email': email.toLowerCase(),
      'Phone': cleanPhone,
      'City': city,
      'Registration Date': formattedDate
    }
  });
}

// 🎁 Bonus 2: Create a Summary Report Row
// We calculate total rows removed across all issues
let totalRemoved = removedEmpty + removedDuplicate + removedInvalidEmail + removedInvalidPhone + removedInvalidDate;

cleanedData.push({
  json: {
    'Customer ID': 'SUMMARY REPORT',
    'Full Name': `Total Rows Imported: ${totalImported}`,
    'Email': `Rows Removed (Empty): ${removedEmpty}`,
    'Phone': `Duplicate Rows Removed: ${removedDuplicate}`,
    'City': `Invalid Emails Removed: ${removedInvalidEmail} | Invalid Phones Removed: ${removedInvalidPhone}`,
    'Registration Date': `Final Row Count: ${cleanedData.length}`
  }
});

return cleanedData;
